import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

export default function OtpVerify() {
  const [otp, setOtp] = useState("");
  const [message, setMessage] = useState("");
  const navigate = useNavigate();

  const mobile = localStorage.getItem("mobile");

  useEffect(() => {
    if (!mobile) navigate("/");
  }, [mobile]);

  const handleVerify = async () => {
    if (!otp.trim()) {
      setMessage("Please enter OTP");
      return;
    }

    try {
      const res = await axios.post(
        `http://localhost:8080/otp/verify?mobile=${mobile}&otp=${otp}`
      );
      setMessage(res.data);

      if (res.data.toLowerCase().includes("verified")) {
        setTimeout(() => navigate("/add-user"), 1000);
      }
    } catch {
      setMessage("OTP verification failed");
    }
  };

  return (
    <div className="auth-page">
      <div className="auth-card">
        <h2 className="text-center mb-2 text-primary">Verify OTP</h2>
        <p className="text-center text-muted">Sent to {mobile}</p>

        <input
          type="text"
          className="form-control otp-box mb-3"
          placeholder="Enter OTP"
          value={otp}
          onChange={(e) => setOtp(e.target.value)}
        />

        <button className="btn btn-success w-100" onClick={handleVerify}>
          Verify OTP
        </button>

        {message && (
          <p className="text-center mt-3 fw-bold text-success">{message}</p>
        )}
      </div>
    </div>
  );
}
